package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class ApprovalDiagnosticBrowserAcceptance {
 static void revokedReviewer(WorkflowSupport h,boolean passwordReset) throws Exception {
  h.account("RevokedReviewer","agent");String record=h.add("incident").get("sys_id").toString(),reviews="/api/openservice/records/incident/"+record+"/approvals",approval=ApprovalAcceptance.create(h,reviews,"RevokedReviewer","admin");
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}
  if(passwordReset)DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_user SET password_reset_required=1 WHERE name='RevokedReviewer'");
  else{var denied=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));denied.put("record_roles",map("read",List.of("admin")));ApprovalAcceptance.writeSchema(h,denied);}
  try{assertEquals(passwordReset?409:403,h.json("POST","/api/openservice/operations/approval-reminders/"+approval,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_notice WHERE user_id=?",RecordAccess.owner(db,"RevokedReviewer")));}if(!passwordReset){assertEquals(0,objects(parsed(h.get("/api/openservice/me/approvals",auth("RevokedReviewer"))).get("result")).size());assertFalse(html(h.get("/account/approvals",auth("RevokedReviewer"))).contains(approval));assertEquals(403,h.get("/record/incident/"+record+"/approvals",auth("RevokedReviewer")).statusCode());String fresh=h.add("incident").get("sys_id").toString();assertEquals(400,h.json("POST","/api/openservice/records/incident/"+fresh+"/approvals",ApprovalAcceptance.proposal("RevokedReviewer"),auth("admin")).statusCode());}}finally{ApprovalAcceptance.writeSchema(h,original);}
 }
 static void run(WorkflowSupport h) throws Exception {
  h.account("ExplainReviewer","agent");String record=h.add("incident").get("sys_id").toString(),reviews="/api/openservice/records/incident/"+record+"/approvals",approval=ApprovalAcceptance.create(h,reviews,"ExplainReviewer","admin"),path="/admin/approvals/"+approval+"/diagnostics";
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}var denied=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));denied.put("record_roles",map("read",List.of("agent")));ApprovalAcceptance.writeSchema(h,denied);try{assertEquals(403,h.get("/api/openservice/operations/approval-diagnostics/"+approval,auth("admin")).statusCode());assertEquals(403,h.json("POST","/api/openservice/operations/approval-reminders/"+approval,map(),auth("admin")).statusCode());}finally{ApprovalAcceptance.writeSchema(h,original);}
  var reviewerDenied=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));reviewerDenied.put("record_roles",map("read",List.of("admin")));ApprovalAcceptance.writeSchema(h,reviewerDenied);try{assertTrue(html(h.get(path,auth("admin"))).contains("reviewer_permission_changed"));assertEquals(403,h.protectedForm(path,map(),auth("admin")).statusCode());assertEquals(403,h.json("POST","/api/openservice/operations/approval-reminders/"+approval,map(),auth("admin")).statusCode());}finally{ApprovalAcceptance.writeSchema(h,original);}
  var page=h.get(path,auth("admin"));assertEquals(200,page.statusCode(),html(page));assertTrue(html(page).contains("awaiting_decision"));assertEquals(403,h.get(path,auth("ExplainReviewer")).statusCode());assertEquals(302,h.get(path,null).statusCode());assertEquals(404,h.get(path.replace(approval,id()),auth("admin")).statusCode());assertEquals(400,h.get(path+"?extra=x",auth("admin")).statusCode());assertEquals(403,h.form(path,map(),auth("admin")).statusCode());assertEquals(400,h.protectedForm(path,map("extra","x"),auth("admin")).statusCode());
  h.json("POST","/api/openservice/me/notifications",map("enabled",false),auth("ExplainReviewer"));assertTrue(html(h.protectedForm(path,map(),auth("admin"))).contains("No notice delivered"));h.json("POST","/api/openservice/me/notifications",map("enabled",true),auth("ExplainReviewer"));assertTrue(html(h.protectedForm(path,map(),auth("admin"))).contains("Reminder delivered"));assertTrue(html(h.protectedForm(path,map(),auth("admin"))).contains("already retained"));assertEquals(2,ApprovalAssignmentAcceptance.notices(h,"ExplainReviewer").size());
  DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_user SET active=0 WHERE name='ExplainReviewer'");assertTrue(html(h.get(path,auth("admin"))).contains("reviewer_unavailable"));assertEquals(409,h.protectedForm(path,map(),auth("admin")).statusCode());DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_user SET active=1 WHERE name='ExplainReviewer'");
  DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_user SET password_reset_required=1 WHERE name='ExplainReviewer'");assertTrue(html(h.get(path,auth("admin"))).contains("reviewer_unavailable"));assertEquals(409,h.protectedForm(path,map(),auth("admin")).statusCode());assertEquals(409,h.json("POST","/api/openservice/operations/approval-reminders/"+approval,map(),auth("admin")).statusCode());DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_user SET password_reset_required=0 WHERE name='ExplainReviewer'");
  assertEquals(200,h.json("PATCH","/api/now/table/incident/"+record,map("description","Changed proposal"),auth("admin")).statusCode());assertTrue(html(h.get(path,auth("admin"))).contains("proposal_changed"));assertEquals(409,h.protectedForm(path,map(),auth("admin")).statusCode());
 }
 static void browser(BrowserTest h) throws Exception {
  String name="Explain"+id().substring(0,8),record;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",name,"password",PASSWORD,"role","agent"));record=Service.create(db,"incident",map("short_description","Explain this review"),"admin").get("sys_id").toString();Approvals.request(db,"incident",record,db.one("SELECT * FROM os_user WHERE user_id=?",actor),ApprovalAcceptance.proposal(name));db.connection.commit();}
  try(var p=Playwright.create();var b=p.chromium().launch();var c=b.newContext()){var page=c.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/incident/"+record+"/approvals");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect review readiness")).press("Enter");for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}assertThat(page.locator("main")).containsText("awaiting_decision");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/approval-diagnostics-"+theme+".png")).setFullPage(true));}page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Send in-app reminder")).press("Enter");assertThat(page.locator("[role=status]")).containsText("Reminder delivered");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Send in-app reminder")).click();assertThat(page.locator("[role=status]")).containsText("already retained");}
 }
}
